def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, lb, ub)

    def mutate(x):
        return x + (ub - lb) * rng.uniform(-1, 1, size=dim)

    def crossover(p1, p2):
        c = 0.5
        mask = rng.random(size=dim) < c
        return np.where(mask, p1, p2)

    population_size = 100
    population = np.zeros((population_size, dim))
    for i in range(population_size):
        population[i] = clip(ub - lb * rng.uniform(size=dim))

    for _ in range(budget):
        fitnesses = [func(clip(x)) for x in population]
        idxs = np.argsort(fitnesses)[:int(population_size/2)]
        parents = population[idxs]

        offspring = []
        while len(offspring) < population_size:
            p1, p2 = rng.choice(parents, size=2, replace=False)
            child = crossover(p1, p2)
            if func(clip(child)) < func(clip(p1)):
                offspring.append(child)
            elif np.random.rand() < 0.5:
                offspring.append(mutate(child))

        population = np.array(offspring)

    best_idx = np.argmin([func(clip(x)) for x in population])
    return clip(population[best_idx])

def algorithm(func, dim, lb, ub, budget, rng):
    def clip(x):
        return np.clip(x, a_min=lb, a_max=ub)

    temp = 1000
    T = 0.9
    cooling_rate = 0.9995
    solution = np.zeros(dim)
    best_solution = np.zeros(dim)
    current_value = func(solution)

    for _ in range(budget):
        new_solution = clip(solution + rng.normal(size=dim) * 1e-2)
        new_value = func(new_solution)

        if new_value < current_value:
            solution = new_solution
            current_value = new_value

            if current_value < func(best_solution):
                best_solution = new_solution

        delta = current_value - new_value
        acceptance_prob = np.exp(-delta / temp)
        if rng.random() < acceptance_prob:
            solution = new_solution
            current_value = new_value

        temp *= cooling_rate
        if temp < 1e-5:
            break

    return best_solution
